import { CONFIG } from './config.js'

/* ---------- URL persistence: seed + deaths (+ loops) ---------- */
export function readUrlParams() {
  const p = new URLSearchParams(window.location.search)
  const seed = p.get('seed') || String(Math.floor(Math.random() * 89999) + 10000)
  const deaths = Math.max(0, parseInt(p.get('deaths') || '0', 10) || 0)
  const loops = Math.max(0, parseInt(p.get('runs') || '0', 10) || 0)
  return { seed, deaths, loops }
}

export function writeUrlParams(seed, deaths, loops) {
  const url = `${window.location.pathname}?seed=${encodeURIComponent(seed)}&deaths=${deaths}&runs=${loops}`
  window.history.replaceState(null, '', url)
}

/* ---------- single consolidated runtime state ---------- */
export function createGameState(seed, deaths, loops) {
  return {
    phase: 'loading',       // loading | menu | mutation | playing | paused | dead | victory | trapped
    seed, deaths, loops,
    run: 1 + deaths + loops,
    corruption: 0,
    parts: { collected: 0, total: 0 },
    inkCharges: CONFIG.INK_START,
    blueprints: [],         // [{roomId, mode, note, layoutKey, fade}]
    markMode: 0,
    mutation: null,
    mood: null,             // inherited emotional state: afraid | calm | manic
    moodTimer: 0,
    stamina: CONFIG.STAMINA_MAX,
    stunned: 0,             // cognitive rejection timer
    hidden: false,          // inside wardrobe
    damageFx: 0,            // desaturation tremor timer
    trap: null,             // { timer, shardId } during recursive trap
    judgment: false,        // all parts -> omega frozen, exit stable
    omegaActive: deaths >= 7,
    omegaNear: false,
    deathCause: null,
    lastDeathPos: null,     // previous run death world position
    lastDeathRoom: null,
    tockLog: '',            // current narration line
    tockLogTimer: 0,
    prompt: '',             // interact prompt text
    markFlash: 0,
    echoRecord: [],         // ring buffer of {x,z,rotY,t}
    roomLabel: '',
    fps: 60,
  }
}

/* ---------- tiny external store bridging game loop -> React ---------- */
const listeners = new Set()
let snapshot = null
let version = 0

export function pushHud(partial) {
  snapshot = { ...(snapshot || {}), ...partial, _v: ++version }
  for (const fn of listeners) fn()
}
export function getHud() {
  return snapshot || { _v: 0, phase: 'menu' }
}
export function subscribeHud(fn) {
  listeners.add(fn)
  return () => listeners.delete(fn)
}
