{"file_path":"/logs/artifacts/project/src/game/layout.js","content":"/* ================= Procedural Mansion Layout (pure, worker-safe) ================= */
import { makeRng, layoutSeed } from './rng.js'
import { CONFIG } from './config.js'

const TYPE_DEFS = {
  start:      { wMin: 6, wMax: 8,  h: 4.0, weight: 0 },
  corridor:   { wMin: 4, wMax: 6,  h: 3.2, weight: 50 },
  hall:       { wMin: 5, wMax: 8,  h: 4.2, weight: 18 },
  grandhall:  { wMin: 8, wMax: 11, h: 6.5, weight: 9 },
  attic:      { wMin: 5, wMax: 7,  h: 2.15, weight: 13 },
  pipes:      { wMin: 5, wMax: 8,  h: 3.0, weight: 12 },
  clockpivot: { wMin: 6, wMax: 9,  h: 5.0, weight: 7 },
  foyer:      { wMin: 6, wMax: 8,  h: 4.0, weight: 0 },
}

export function generateLayout(baseSeed, deaths, loops, lastDeathPos) {
  const rng = makeRng(layoutSeed(baseSeed, deaths, loops))
  const roomCount = Math.min(CONFIG.BASE_ROOMS + CONFIG.ROOMS_PER_DEATH * deaths, CONFIG.MAX_ROOMS)
  const rooms = []
  const corridors = []
  const adjacency = new Map()

  function link(a, b, corridorId) {
    if (!adjacency.has(a)) adjacency.set(a, [])
    if (!adjacency.has(b)) adjacency.set(b, [])
    adjacency.get(a).push({ room: b, corridor: corridorId })
    adjacency.get(b).push({ room: a, corridor: corridorId })
  }

  function pickType(r) {
    let total = 0
    for (const k in TYPE_DEFS) total += TYPE_DEFS[k].weight
    let roll = r.next() * total
    for (const k in TYPE_DEFS) {
      roll -= TYPE_DEFS[k].weight
      if (roll <= 0) return k
    }
    return 'corridor'
  }

  function makeRoom(id, type, x, z) {
    const def = TYPE_DEFS[type]
    const w = rng.range(def.wMin, def.wMax)
    const d = rng.range(def.wMin, def.wMax)
    return {
      id, type, x, z, w, d, h: def.h,
      texSeed: rng.int(1, 99999),
      glitch: type === 'clockpivot' ? rng.range(0.5, 1) : rng.range(0, 0.25),
      lamps: [], pendulums: 0, furniture: [],
    }
  }

  // random-walk chain with occasional branch parents
  rooms.push(makeRoom(0, 'start', 0, 0))
  let frontier = 0
  for (let i = 1; i < roomCount; i++) {
    const parent = rng.chance(0.28) ? rng.int(0, rooms.length - 1) : frontier
    const pr = rooms[parent]
    const side = rng.int(0, 3) // 0:-z 1:+x 2:+z 3:-x
    const horiz = side === 1 || side === 3
    const sgn = side === 1 || side === 2 ? 1 : -1
    const type = pickType(rng)
    const probe = makeRoom(i, type, 0, 0)
    const corLen = rng.range(2.2, 4.6)
    const corW = 2.2
    const offset = (horiz ? pr.w / 2 : pr.d / 2) + corLen + (horiz ? probe.w / 2 : probe.d / 2)
    const x = pr.x + (horiz ? sgn * offset : rng.range(-pr.w / 4, pr.w / 4))
    const z = pr.z + (horiz ? rng.range(-pr.d / 4, pr.d / 4) : sgn * offset)
    const room = makeRoom(i, type, x, z)
    rooms.push(room)
    const low = type === 'attic' || rng.chance(0.1)
    corridors.push({
      id: corridors.length, from: parent, to: i, low,
      x: horiz ? (pr.x + sgn * (pr.w / 2 + corLen / 2)) : x,
      z: horiz ? z : (pr.z + sgn * (pr.d / 2 + corLen / 2)),
      w: horiz ? corLen + 0.9 : corW, d: horiz ? corW : corLen + 0.9,
      h: low ? 1.35 : 3.0,
    })
    link(parent, i, corridors.length - 1)
    frontier = i
  }

  // exit = farthest room from start
  let exitId = 0, best = -1
  for (const r of rooms) {
    const dist = Math.hypot(r.x, r.z)
    if (dist > best) { best = dist; exitId = r.id }
  }
  rooms[exitId].type = rooms[exitId].type === 'start' ? 'hall' : rooms[exitId].type
  const exitRoom = rooms[exitId]

  // hidden first foyer: mirror-flipped copy of run-1 start, run >= 7 only
  if (deaths >= 7) {
    const anchor = rooms[rng.int(Math.floor(rooms.length * 0.4), rooms.length - 1)]
    const foyer = makeRoom(rooms.length, 'foyer', anchor.x + anchor.w + 8, anchor.z + anchor.d + 8)
    foyer.mirror = true
    rooms.push(foyer)
    corridors.push({ id: corridors.length, from: anchor.id, to: foyer.id, low: false,
      x: (anchor.x + foyer.x) / 2, z: (anchor.z + foyer.z) / 2,
      w: Math.abs(foyer.x - anchor.x) + 1, d: 2.2, h: 3.0 })
    link(anchor.id, foyer.id, corridors.length - 1)
  }

  /* ---------- furniture / lamps / decor ---------- */
  for (const r of rooms) {
    const put = (type, extra = {}) => {
      const a = rng.range(0, Math.PI * 2)
      const rad = rng.range(0.25, 0.42)
      r.furniture.push({
        type,
        x: r.x + Math.cos(a) * (r.w / 2) * rad * 2 * 0.8,
        z: r.z + Math.sin(a) * (r.d / 2) * rad * 2 * 0.8,
        rot: rng.range(0, Math.PI * 2),
        variant: rng.int(0, 3),
        ...extra,
      })
    }
    const lampN = r.type === 'grandhall' ? 3 : r.type === 'corridor' ? 1 : 2
    for (let i = 0; i < lampN; i++) {
      const side = rng.int(0, 3)
      const horiz = side === 1 || side === 3
      r.lamps.push({
        x: r.x + (horiz ? (side === 1 ? 1 : -1) * (r.w / 2 - 0.25) : rng.range(-r.w / 3, r.w / 3)),
        z: r.z + (horiz ? rng.range(-r.d / 3, r.d / 3) : (side === 2 ? 1 : -1) * (r.d / 2 - 0.25)),
        y: rng.range(1.6, Math.min(2.6, r.h - 0.5)),
      })
    }
    if (r.type === 'grandhall') {
      put('column'); put('column'); put('chandelier', { x: r.x, z: r.z, rot: 0 })
      put('longcase'); put('longcase'); if (rng.chance(0.7)) put('wardrobe')
      put('table'); r.pendulums = rng.int(1, 2)
    } else if (r.type === 'corridor') {
      if (rng.chance(0.55)) put('longcase', { toppled: rng.chance(0.6) })
      if (rng.chance(0.3)) put('gears')
      if (rng.chance(0.25)) put('wardrobe')
    } else if (r.type === 'attic') {
      put('crate'); put('crate'); if (rng.chance(0.5)) put('wardrobe')
      if (rng.chance(0.4)) put('gears')
    } else if (r.type === 'pipes') {
      put('pipeset'); put('valve'); if (rng.chance(0.4)) put('gears')
    } else if (r.type === 'clockpivot') {
      put('biggear'); put('biggear'); put('longcase'); r.pendulums = rng.int(2, 4)
      if (rng.chance(0.5)) put('wardrobe')
    } else if (r.type === 'hall' || r.type === 'start' || r.type === 'foyer') {
      if (rng.chance(0.6)) put('longcase')
      if (rng.chance(0.45)) put('wardrobe')
      if (rng.chance(0.5)) put('table')
      if (rng.chance(0.3)) put('stairs')
      r.pendulums = rng.int(0, 1)
    }
  }

  /* ---------- item placement ---------- */
  const partRooms = []
  const weighted = rooms.filter(r => r.id !== 0 && r.type !== 'foyer')
  const partCount = rng.int(CONFIG.PARTS_REQUIRED, 12)
  const weights = weighted.map(r => r.type === 'grandhall' ? 4 : r.type === 'clockpivot' ? 3 : r.type === 'pipes' ? 0.7 : 1.4)
  while (partRooms.length < partCount) {
    let total = 0
    for (const r of weighted) if (!partRooms.includes(r.id)) total += weights[weighted.indexOf(r)]
    if (total <= 0) break
    let roll = rng.next() * total
    for (const r of weighted) {
      if (partRooms.includes(r.id)) continue
      roll -= weights[weighted.indexOf(r)]
      if (roll <= 0) { partRooms.push(r.id); break }
    }
  }
  const randIn = (r, m = 0.6) => ({
    x: r.x + rng.range(-r.w / 2 + m, r.w / 2 - m),
    z: r.z + rng.range(-r.d / 2 + m, r.d / 2 - m),
  })
  const parts = partRooms.map((roomId, i) => ({ id: i, roomId, ...randIn(rooms[roomId]) }))

  const scatter = (count, types) => {
    const out = []
    const pool = rooms.filter(r => r.id !== 0 && types.includes(r.type))
    for (let i = 0; i < count && pool.length; i++) {
      const r = pool[rng.int(0, pool.length - 1)]
      out.push({ id: i, roomId: r.id, ...randIn(r) })
    }
    return out
  }
  const inks = scatter(rng.int(3, 5), ['hall', 'grandhall', 'attic', 'corridor'])
  const fragments = scatter(rng.int(2, 4), ['hall', 'grandhall', 'clockpivot'])
  const echoes = scatter(rng.int(1, 3), ['grandhall', 'clockpivot', 'hall'])

  const trapCount = Math.min(1 + Math.floor(roomCount / 18) + Math.floor(deaths / 2), 10)
  const traps = scatter(trapCount, ['corridor', 'pipes', 'hall'])
  const fracCount = Math.min(2 + Math.floor(deaths / 2), 8)
  const fractures = scatter(fracCount, ['corridor', 'pipes'])

  /* ---------- enemy anchors ---------- */
  const farFromStart = rooms.filter(r => Math.hypot(r.x, r.z) > 12)
  const tickRoom = (farFromStart[rng.int(0, farFromStart.length - 1)] || rooms[1]).id
  let hotspot
  if (lastDeathPos) {
    let bestR = rooms[1], bd = Infinity
    for (const r of rooms) {
      const d = Math.hypot(r.x - lastDeathPos.x, r.z - lastDeathPos.z)
      if (d < bd) { bd = d; bestR = r }
    }
    hotspot = { x: bestR.x, z: bestR.z, roomId: bestR.id }
  } else {
    const pr = rooms.find(r => r.type === 'pipes') || rooms[1]
    hotspot = { x: pr.x, z: pr.z, roomId: pr.id }
  }

  return {
    rooms, corridors,
    adjacency: [...adjacency.entries()].map(([k, v]) => [k, v]),
    parts, inks, fragments, echoes, traps, fractures,
    start: { x: rooms[0].x, z: rooms[0].z },
    exit: { x: exitRoom.x, z: exitRoom.z, roomId: exitId },
    tickRoom, hotspot,
    roomCount: rooms.length,
  }
}

/* ---------- pure collision helpers (shared by player + enemies) ---------- */
export function makeCollisionIndex(layout) {
  const rects = []
  for (const r of layout.rooms) rects.push({ x: r.x, z: r.z, w: r.w, d: r.d, roomId: r.id, low: false, kind: 'room', type: r.type })
  for (const c of layout.corridors) rects.push({ x: c.x, z: c.z, w: c.w, d: c.d, roomId: c.to, low: c.low, kind: 'corridor' })
  const blockers = []
  for (const r of layout.rooms) {
    for (const f of r.furniture) {
      if (f.type === 'wardrobe' || f.type === 'longcase' || f.type === 'crate' || f.type === 'table' || f.type === 'column') {
        const s = f.type === 'column' ? 0.55 : f.type === 'table' ? 0.9 : f.type === 'crate' ? 0.6 : 0.62
        blockers.push({ x: f.x, z: f.z, hw: s, hd: s, type: f.type })
      }
    }
  }
  return { rects, blockers }
}

export function pointInRect(px, pz, rect, margin = 0) {
  return Math.abs(px - rect.x) <= rect.w / 2 - margin && Math.abs(pz - rect.z) <= rect.d / 2 - margin
}

export function locate(index, px, pz, margin = 0) {
  // returns { inside, roomRect, lowCorridor } — first matching room rect wins for identity
  let inside = false, roomRect = null, lowCorridor = false
  for (const rect of index.rects) {
    if (pointInRect(px, pz, rect, margin)) {
      inside = true
      if (rect.kind === 'corridor' && rect.low) lowCorridor = true
      if (!roomRect && rect.kind === 'room') roomRect = rect
    }
  }
  return { inside, roomRect, lowCorridor }
}

export function blockedByFurniture(index, px, pz, radius) {
  for (const b of index.blockers) {
    if (Math.abs(px - b.x) < b.hw + radius && Math.abs(pz - b.z) < b.hd + radius) return b
  }
  return null
}
"}

