{"file_path":"/logs/artifacts/project/src/game/input.js","content":"/* ================= Input: keyboard / mouse-lock / touch ================= */

export function createInput(canvas, callbacks) {
  const keys = new Set()
  const input = {
    keys,
    lookDX: 0, lookDY: 0,
    dragging: false,
    locked: false,
    touch: { moveX: 0, moveY: 0, sprint: false, crouch: false },
    once: {},
  }

  const KEYMAP = {
    KeyW: 'forward', ArrowUp: 'forward',
    KeyS: 'back', ArrowDown: 'back',
    KeyA: 'left', ArrowLeft: 'left',
    KeyD: 'right', ArrowRight: 'right',
    ShiftLeft: 'sprint', ShiftRight: 'sprint',
    ControlLeft: 'crouch', ControlRight: 'crouch', KeyX: 'crouch',
    Space: 'jump',
    KeyE: 'interact',
    KeyF: 'mark',
    KeyC: 'cycleMode',
    Tab: 'blueprint',
    Escape: 'pause', KeyP: 'pause',
  }
  const onKeys = { interact: 'interact', mark: 'mark', cycleMode: 'cycleMode', blueprint: 'blueprint', jump: 'jump', pause: 'pause' }

  function onKeyDown(e) {
    const action = KEYMAP[e.code]
    if (!action) return
    if (['forward', 'back', 'left', 'right', 'jump', 'blueprint', 'cycleMode', 'pause'].includes(action)) e.preventDefault()
    if (onKeys[action] && !keys.has(action)) input.once[action] = true
    keys.add(action)
  }
  function onKeyUp(e) {
    const action = KEYMAP[e.code]
    if (action) keys.delete(action)
  }

  function requestLock() {
    if (!input.locked && canvas.requestPointerLock) {
      canvas.requestPointerLock().catch?.(() => {})
    }
  }
  function onLockChange() {
    input.locked = document.pointerLockElement === canvas
    callbacks.onLockChange?.(input.locked)
  }

  function onMouseMove(e) {
    if (input.locked) {
      input.lookDX += e.movementX
      input.lookDY += e.movementY
    } else if (input.dragging) {
      input.lookDX += e.movementX
      input.lookDY += e.movementY
    }
  }
  function onMouseDown(e) {
    if (e.target === canvas) {
      input.dragging = true
      requestLock()
    }
  }
  function onMouseUp() { input.dragging = false }

  /* touch: left half = move stick, right half = look drag */
  let moveTouchId = null, lookTouchId = null
  let moveOrigin = { x: 0, y: 0 }, lookLast = { x: 0, y: 0 }
  function onTouchStart(e) {
    for (const t of e.changedTouches) {
      if (t.clientX < window.innerWidth * 0.45 && moveTouchId === null) {
        moveTouchId = t.identifier
        moveOrigin = { x: t.clientX, y: t.clientY }
      } else if (lookTouchId === null) {
        lookTouchId = t.identifier
        lookLast = { x: t.clientX, y: t.clientY }
      }
    }
  }
  function onTouchMove(e) {
    for (const t of e.changedTouches) {
      if (t.identifier === moveTouchId) {
        input.touch.moveX = Math.max(-1, Math.min(1, (t.clientX - moveOrigin.x) / 55))
        input.touch.moveY = Math.max(-1, Math.min(1, (t.clientY - moveOrigin.y) / 55))
      } else if (t.identifier === lookTouchId) {
        input.lookDX += (t.clientX - lookLast.x) * 2.2
        input.lookDY += (t.clientY - lookLast.y) * 2.2
        lookLast = { x: t.clientX, y: t.clientY }
      }
    }
    e.preventDefault()
  }
  function onTouchEnd(e) {
    for (const t of e.changedTouches) {
      if (t.identifier === moveTouchId) { moveTouchId = null; input.touch.moveX = 0; input.touch.moveY = 0 }
      if (t.identifier === lookTouchId) lookTouchId = null
    }
  }

  window.addEventListener('keydown', onKeyDown)
  window.addEventListener('keyup', onKeyUp)
  document.addEventListener('pointerlockchange', onLockChange)
  window.addEventListener('mousemove', onMouseMove)
  window.addEventListener('mousedown', onMouseDown)
  window.addEventListener('mouseup', onMouseUp)
  canvas.addEventListener('touchstart', onTouchStart, { passive: false })
  canvas.addEventListener('touchmove', onTouchMove, { passive: false })
  canvas.addEventListener('touchend', onTouchEnd)
  canvas.addEventListener('touchcancel', onTouchEnd)

  input.destroy = () => {
    window.removeEventListener('keydown', onKeyDown)
    window.removeEventListener('keyup', onKeyUp)
    document.removeEventListener('pointerlockchange', onLockChange)
    window.removeEventListener('mousemove', onMouseMove)
    window.removeEventListener('mousedown', onMouseDown)
    window.removeEventListener('mouseup', onMouseUp)
    canvas.removeEventListener('touchstart', onTouchStart)
    canvas.removeEventListener('touchmove', onTouchMove)
    canvas.removeEventListener('touchend', onTouchEnd)
    canvas.removeEventListener('touchcancel', onTouchEnd)
  }
  input.consume = (action) => {
    if (input.once[action]) { input.once[action] = false; return true }
    return false
  }
  input.resetLook = () => { input.lookDX = 0; input.lookDY = 0 }
  input.axisX = () => (keys.has('right') ? 1 : 0) - (keys.has('left') ? 1 : 0) + input.touch.moveX
  input.axisZ = () => (keys.has('forward') ? 1 : 0) - (keys.has('back') ? 1 : 0) - input.touch.moveY
  input.has = (a) => keys.has(a) || (a === 'sprint' && input.touch.sprint) || (a === 'crouch' && input.touch.crouch)
  return input
}
"}

