/* Graph: sources -> buses -> crusher -> lowpass(corruption) -> master -> compressor -> out */

export function createAudioEngine() {
  const A = {
    ctx: null, master: null, lowpass: null, crusher: null, bus: {},
    corruption: 0, muted: false, started: false,
  }

  function init() {
    if (A.ctx) return
    const ctx = new (window.AudioContext || window.webkitAudioContext)()
    A.ctx = ctx
    A.master = ctx.createGain(); A.master.gain.value = 0.8
    const comp = ctx.createDynamicsCompressor()
    A.lowpass = ctx.createBiquadFilter(); A.lowpass.type = 'lowpass'; A.lowpass.frequency.value = 16000
    A.crusher = ctx.createWaveShaper(); setCrush(0)
    A.master.connect(comp); comp.connect(ctx.destination)
    A.lowpass.connect(A.master)
    A.crusher.connect(A.lowpass)
    A.bus = {}
    for (const name of ['bgm', 'sfx', 'ui', 'amb']) {
      const g = ctx.createGain(); g.connect(A.crusher); A.bus[name] = g
    }
    A.bus.bgm.gain.value = 0.5
    A.bus.sfx.gain.value = 0.9
    A.bus.ui.gain.value = 0.7
    A.bus.amb.gain.value = 0.55
    // shared noise buffer
    const len = ctx.sampleRate * 2
    A.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate)
    const data = A.noiseBuf.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    startBgm()
    startAmbience()
    A.started = true
  }

  function resume() { if (A.ctx && A.ctx.state === 'suspended') A.ctx.resume() }

  function setCrush(amount) {
    if (!A.ctx) return
    const steps = Math.max(2, Math.round(256 * (1 - amount * 0.96)))
    const curve = new Float32Array(4096)
    for (let i = 0; i < 4096; i++) {
      const x = (i / 4096) * 2 - 1
      curve[i] = Math.round(x * steps) / steps
    }
    A.crusher.curve = curve
  }

  function setCorruption(c) {
    A.corruption = c
    if (!A.ctx) return
    const t = c / 100
    A.lowpass.frequency.setTargetAtTime(16000 * Math.pow(280 / 16000, t), A.ctx.currentTime, 0.4)
    setCrush(t)
    if (A.droneDetune) A.droneDetune.detune.setTargetAtTime(t * 60, A.ctx.currentTime, 0.5)
    if (A.subGain) A.subGain.gain.setTargetAtTime(0.12 + t * 0.1, A.ctx.currentTime, 0.5)
  }

  /* ---------- helpers ---------- */
  function env(g, t0, a, peak, d, end = 0.0001) {
    g.gain.setValueAtTime(0.0001, t0)
    g.gain.linearRampToValueAtTime(peak, t0 + a)
    g.gain.exponentialRampToValueAtTime(end, t0 + a + d)
  }
  function osc(type, freq, t0) {
    const o = A.ctx.createOscillator()
    o.type = type; o.frequency.setValueAtTime(freq, t0)
    return o
  }
  function noise(t0, dur) {
    const s = A.ctx.createBufferSource()
    s.buffer = A.noiseBuf; s.loop = true
    s.start(t0); s.stop(t0 + dur + 0.05)
    return s
  }
  function pan(node, p) {
    const pn = A.ctx.createStereoPanner()
    pn.pan.value = Math.max(-1, Math.min(1, p))
    node.connect(pn)
    return pn
  }

  /* ---------- BGM: drones + degrading chime scheduler ---------- */
  let chimeTimer = null
  function startBgm() {
    const ctx = A.ctx, t0 = ctx.currentTime
    const droneGain = ctx.createGain(); droneGain.gain.value = 0.11
    const d1 = osc('sawtooth', 55, t0)
    const d2 = osc('sawtooth', 55.6, t0)
    A.droneDetune = d2
    const dFilter = ctx.createBiquadFilter(); dFilter.type = 'lowpass'; dFilter.frequency.value = 320
    d1.connect(dFilter); d2.connect(dFilter); dFilter.connect(droneGain); droneGain.connect(A.bus.bgm)
    d1.start(t0); d2.start(t0)
    const sub = osc('sine', 36.7, t0)
    A.subGain = ctx.createGain(); A.subGain.gain.value = 0.12
    sub.connect(A.subGain); A.subGain.connect(A.bus.bgm)
    sub.start(t0)
    scheduleChime()
  }

  function chime(degrade) {
    const ctx = A.ctx, t0 = ctx.currentTime
    const base = 196 * (degrade > 0.5 ? Math.pow(2, (Math.random() - 0.5) * 0.09) : 1)
    const partials = [1, 2.74, 5.43, 8.21]
    const gains = [0.5, 0.24, 0.13, 0.06]
    for (let i = 0; i < partials.length; i++) {
      const o = osc('sine', base * partials[i] * (1 + degrade * (Math.random() - 0.5) * 0.05), t0)
      const g = ctx.createGain()
      env(g, t0, 0.004, gains[i], 2.2 + Math.random())
      o.connect(g); g.connect(A.bus.bgm)
      o.start(t0); o.stop(t0 + 2.6)
    }
    if (degrade > 0.25) { // metal-fatigue rattle
      const n = noise(t0, 0.4)
      const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 900; f.Q.value = 4
      const g = ctx.createGain(); env(g, t0, 0.002, degrade * 0.2, 0.4)
      n.connect(f); f.connect(g); g.connect(A.bus.bgm)
    }
  }
  function scheduleChime() {
    if (chimeTimer) clearTimeout(chimeTimer)
    const wait = 7000 + Math.random() * 8000
    chimeTimer = setTimeout(() => {
      if (A.ctx) { chime(A.corruption / 100); scheduleChime() }
    }, wait)
  }

  function startAmbience() {
    // room-tone wind + slow clock tick
    const ctx = A.ctx, t0 = ctx.currentTime
    const n = ctx.createBufferSource(); n.buffer = A.noiseBuf; n.loop = true
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 240
    const g = ctx.createGain(); g.gain.value = 0.05
    n.connect(f); f.connect(g); g.connect(A.bus.amb)
    n.start(t0)
    const tick = () => {
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const o = osc('square', 1400, t)
      const tg = ctx.createGain(); env(tg, t, 0.001, 0.045, 0.03)
      o.connect(tg); tg.connect(A.bus.amb)
      o.start(t); o.stop(t + 0.05)
      setTimeout(tick, 1000)
    }
    setTimeout(tick, 1000)
  }

  /* ---------- one-shot SFX ---------- */
  const api = {
    init, resume, setCorruption,
    get started() { return A.started },

    footstep(volume = 0.5, sprint = false) {
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const n = noise(t, 0.09)
      const f = A.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = sprint ? 700 : 420
      const g = A.ctx.createGain(); env(g, t, 0.004, 0.16 * volume, 0.09)
      n.connect(f); f.connect(g); g.connect(A.bus.sfx)
    },

    sonarPing(panPos) { // TICK-a reversed sonar — directionally ambiguous
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const o = osc('sine', 320, t)
      o.frequency.exponentialRampToValueAtTime(1900, t + 0.55) // reversed sweep feel
      const g = A.ctx.createGain()
      g.gain.setValueAtTime(0.0001, t)
      g.gain.exponentialRampToValueAtTime(0.14, t + 0.5) // slow attack = reversed
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.62)
      o.connect(g); pan(g, panPos).connect(A.bus.sfx)
      o.start(t); o.stop(t + 0.7)
    },

    tockLog() { // mechanical error-log narration babble
      if (!A.ctx) return
      const t = A.ctx.currentTime
      let at = t
      for (let i = 0; i < 7; i++) {
        const o = osc('sawtooth', 180 + Math.random() * 160, at)
        const f = A.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 700 + Math.random() * 900; f.Q.value = 6
        const g = A.ctx.createGain(); env(g, at, 0.01, 0.09, 0.09 + Math.random() * 0.08)
        o.connect(f); f.connect(g); g.connect(A.bus.sfx)
        o.start(at); o.stop(at + 0.25)
        at += 0.14 + Math.random() * 0.09
      }
    },

    inkDrop() { // droplet on copper plate, sharp
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const o = osc('sine', 2100, t)
      o.frequency.exponentialRampToValueAtTime(900, t + 0.12)
      const g = A.ctx.createGain(); env(g, t, 0.001, 0.22, 0.28)
      o.connect(g); g.connect(A.bus.sfx)
      o.start(t); o.stop(t + 0.3)
      const n = noise(t, 0.02)
      const nf = A.ctx.createBiquadFilter(); nf.type = 'highpass'; nf.frequency.value = 4000
      const ng = A.ctx.createGain(); env(ng, t, 0.001, 0.1, 0.02)
      n.connect(nf); nf.connect(ng); ng.connect(A.bus.sfx)
    },

    partPickup() {
      if (!A.ctx) return
      const t = A.ctx.currentTime
      ;[523, 659, 784, 1046].forEach((f, i) => {
        const o = osc('triangle', f, t + i * 0.07)
        const g = A.ctx.createGain(); env(g, t + i * 0.07, 0.005, 0.16, 0.5)
        o.connect(g); g.connect(A.bus.sfx)
        o.start(t + i * 0.07); o.stop(t + i * 0.07 + 0.6)
      })
    },

    trapSweep() { // electronic noise 200hz -> 20hz
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const o = osc('sawtooth', 200, t)
      o.frequency.exponentialRampToValueAtTime(20, t + 1.1)
      const g = A.ctx.createGain(); env(g, t, 0.02, 0.3, 1.15)
      o.connect(g); g.connect(A.bus.sfx)
      o.start(t); o.stop(t + 1.2)
    },

    rejection() {
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const o = osc('square', 90, t)
      o.frequency.linearRampToValueAtTime(45, t + 0.5)
      const g = A.ctx.createGain(); env(g, t, 0.005, 0.35, 0.55)
      o.connect(g); g.connect(A.bus.sfx)
      o.start(t); o.stop(t + 0.6)
    },

    deathRewind() {
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const o = osc('sine', 1200, t)
      o.frequency.exponentialRampToValueAtTime(60, t + 1.8)
      const g = A.ctx.createGain(); env(g, t, 0.3, 0.3, 1.6)
      o.connect(g); g.connect(A.bus.sfx)
      o.start(t); o.stop(t + 2)
      const n = noise(t, 1.8)
      const f = A.ctx.createBiquadFilter(); f.type = 'bandpass'; f.Q.value = 2
      f.frequency.exponentialRampToValueAtTime(120, t + 1.8); f.frequency.setValueAtTime(3000, t)
      const ng = A.ctx.createGain(); env(ng, t, 0.25, 0.2, 1.6)
      n.connect(f); f.connect(ng); ng.connect(A.bus.sfx)
    },

    judgment() {
      if (!A.ctx) return
      const t = A.ctx.currentTime
      ;[130, 196, 260, 392].forEach((f, i) => {
        const o = osc('sine', f, t + i * 0.16)
        const g = A.ctx.createGain(); env(g, t + i * 0.16, 0.02, 0.2, 1.6)
        o.connect(g); g.connect(A.bus.bgm)
        o.start(t + i * 0.16); o.stop(t + i * 0.16 + 1.8)
      })
    },

    fragmentEcho() { // 3s rewound death echo
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const n = noise(t, 3)
      const f = A.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 500; f.Q.value = 1.4
      const g = A.ctx.createGain()
      g.gain.setValueAtTime(0.0001, t)
      g.gain.exponentialRampToValueAtTime(0.22, t + 2.4) // reversed swell
      g.gain.exponentialRampToValueAtTime(0.0001, t + 3)
      f.frequency.setValueAtTime(180, t)
      f.frequency.exponentialRampToValueAtTime(2600, t + 2.6)
      n.connect(f); f.connect(g); g.connect(A.bus.sfx)
    },

    wardrobe(open) {
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const o = osc('triangle', open ? 300 : 220, t)
      o.frequency.linearRampToValueAtTime(open ? 140 : 320, t + 0.22)
      const g = A.ctx.createGain(); env(g, t, 0.01, 0.12, 0.25)
      o.connect(g); g.connect(A.bus.sfx)
      o.start(t); o.stop(t + 0.3)
    },

    uiTick() {
      if (!A.ctx) return
      const t = A.ctx.currentTime
      const o = osc('square', 880, t)
      const g = A.ctx.createGain(); env(g, t, 0.001, 0.06, 0.05)
      o.connect(g); g.connect(A.bus.ui)
      o.start(t); o.stop(t + 0.06)
    },

    destroy() {
      if (chimeTimer) clearTimeout(chimeTimer)
      if (A.ctx) A.ctx.close()
      A.ctx = null
    },
  }
  return api
}
