import * as THREE from 'three'
import { CONFIG } from './config.js'

const C = CONFIG.COL
const paletteMats = [] // materials that shift warm->purple with corruption

function track(mat, lowHex, highHex) {
  mat.userData.low = new THREE.Color(lowHex)
  mat.userData.high = new THREE.Color(highHex)
  paletteMats.push(mat)
  return mat
}
export function updatePalette(corruption) {
  const t = Math.min(1, corruption / 100)
  for (const m of paletteMats) m.color.lerpColors(m.userData.low, m.userData.high, t)
}

const M = {
  wood: () => track(new THREE.MeshLambertMaterial({ color: 0 }), 0x6e4f30, 0x4a3364),
  darkWood: () => track(new THREE.MeshLambertMaterial({ color: 0 }), 0x4a331e, 0x332349),
  brass: () => new THREE.MeshLambertMaterial({ color: 0xc9a35a, emissive: 0x34280e }),
  iron: () => track(new THREE.MeshLambertMaterial({ color: 0 }), 0x5c5c66, 0x4a4460),
  cloth: () => track(new THREE.MeshLambertMaterial({ color: 0 }), 0x7a3b33, 0x512f55),
  glowTeal: () => new THREE.MeshBasicMaterial({ color: C.accent }),
  glowWarm: () => new THREE.MeshBasicMaterial({ color: C.partGlow }),
  lampGlow: () => new THREE.MeshBasicMaterial({ color: C.lamp }),
}
const box = (w, h, d, mat) => new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat)
const cyl = (r1, r2, h, mat, seg = 10) => new THREE.Mesh(new THREE.CylinderGeometry(r1, r2, h, seg), mat)

/* ---------- longcase clock (upright or toppled blocker) ---------- */
export function makeLongcase(toppled = false) {
  const g = new THREE.Group()
  const body = box(0.62, 2.15, 0.4, M.darkWood())
  body.position.y = 1.075
  const head = box(0.72, 0.6, 0.46, M.wood())
  head.position.y = 2.35
  const face = cyl(0.24, 0.24, 0.04, M.brass())
  face.rotation.x = Math.PI / 2
  face.position.set(0, 2.35, 0.24)
  const hand = box(0.03, 0.18, 0.02, new THREE.MeshBasicMaterial({ color: 0x1a120a }))
  hand.position.set(0, 2.35, 0.27)
  hand.userData.isHand = true
  const pendulum = cyl(0.05, 0.05, 0.9, M.brass())
  pendulum.position.set(0, 1.1, 0.12)
  pendulum.userData.isPendulum = true
  const bob = new THREE.Mesh(new THREE.SphereGeometry(0.09, 8, 6), M.brass())
  bob.position.y = -0.5
  pendulum.add(bob)
  g.add(body, head, face, hand, pendulum)
  if (toppled) {
    g.rotation.z = Math.PI / 2 - 0.12
    g.position.y = 0.32
  }
  return g
}

export function makeWardrobe() {
  const g = new THREE.Group()
  const shell = box(1.15, 2.2, 0.65, M.wood())
  shell.position.y = 1.1
  const doorL = box(0.52, 2.0, 0.05, M.darkWood())
  doorL.position.set(-0.27, 1.1, 0.35)
  const doorR = doorL.clone(); doorR.position.x = 0.27
  doorL.userData.isDoor = true; doorR.userData.isDoor = true
  const trim = box(1.22, 0.1, 0.72, M.brass()); trim.position.y = 2.26
  g.add(shell, doorL, doorR, trim)
  g.userData.doors = [doorL, doorR]
  return g
}

export function makeTable() {
  const g = new THREE.Group()
  const top = box(1.3, 0.08, 0.8, M.wood()); top.position.y = 0.78
  g.add(top)
  for (const [x, z] of [[-0.55, -0.3], [0.55, -0.3], [-0.55, 0.3], [0.55, 0.3]]) {
    const leg = box(0.08, 0.78, 0.08, M.darkWood())
    leg.position.set(x, 0.39, z)
    g.add(leg)
  }
  const candle = cyl(0.04, 0.05, 0.18, M.brass()); candle.position.set(0.2, 0.9, 0)
  const flame = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.12, 6), M.lampGlow())
  flame.position.set(0.2, 1.06, 0)
  flame.userData.isFlame = true
  g.add(candle, flame)
  return g
}

export function makeCrate() {
  const g = new THREE.Group()
  const b = box(0.62, 0.62, 0.62, M.wood()); b.position.y = 0.31
  const strap = box(0.66, 0.08, 0.66, M.iron()); strap.position.y = 0.31
  g.add(b, strap)
  return g
}

export function makeGears() {
  const g = new THREE.Group()
  for (let i = 0; i < 3; i++) {
    const r = 0.16 + i * 0.07
    const gear = new THREE.Mesh(new THREE.TorusGeometry(r, 0.05, 6, 10), M.brass())
    gear.position.set((i - 1) * 0.3, r, (i % 2) * 0.2)
    gear.userData.isGear = true
    gear.userData.spin = (i % 2 ? -1 : 1) * (1.5 - i * 0.3)
    g.add(gear)
  }
  return g
}

export function makePipeset() {
  const g = new THREE.Group()
  for (let i = 0; i < 3; i++) {
    const p = cyl(0.09 + i * 0.03, 0.09 + i * 0.03, 2.8, M.iron())
    p.position.set(i * 0.35 - 0.35, 1.4, 0)
    g.add(p)
    const joint = new THREE.Mesh(new THREE.SphereGeometry(0.13 + i * 0.03, 8, 6), M.brass())
    joint.position.set(i * 0.35 - 0.35, 0.6 + i * 0.7, 0)
    g.add(joint)
  }
  return g
}

export function makeValve() {
  const g = new THREE.Group()
  const pipe = cyl(0.12, 0.12, 1.6, M.iron()); pipe.position.y = 0.8
  const wheel = new THREE.Mesh(new THREE.TorusGeometry(0.24, 0.04, 6, 12), M.brass())
  wheel.position.y = 1.2; wheel.rotation.x = Math.PI / 2
  wheel.userData.isGear = true; wheel.userData.spin = 0.4
  g.add(pipe, wheel)
  return g
}

export function makeBiggear() {
  const g = new THREE.Group()
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.85, 0.14, 8, 16), M.brass())
  ring.userData.isGear = true; ring.userData.spin = 0.25
  for (let i = 0; i < 4; i++) {
    const spoke = box(0.1, 1.6, 0.1, M.iron())
    spoke.rotation.z = (i * Math.PI) / 4
    ring.add(spoke)
  }
  g.add(ring)
  return g
}

export function makeColumn() {
  const g = new THREE.Group()
  const shaft = cyl(0.22, 0.26, 5.6, M.wood(), 8); shaft.position.y = 2.8
  const base = box(0.7, 0.3, 0.7, M.darkWood()); base.position.y = 0.15
  const cap = box(0.66, 0.24, 0.66, M.darkWood()); cap.position.y = 5.6
  g.add(shaft, base, cap)
  return g
}

export function makeChandelier(roomH) {
  const g = new THREE.Group()
  const chain = cyl(0.03, 0.03, roomH - 3.4, M.iron())
  chain.position.y = (roomH - 3.4) / 2 + 3.4
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.7, 0.06, 6, 14), M.brass())
  ring.rotation.x = Math.PI / 2; ring.position.y = 3.4
  g.add(chain, ring)
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2
    const c = cyl(0.035, 0.045, 0.2, M.brass())
    c.position.set(Math.cos(a) * 0.7, 3.5, Math.sin(a) * 0.7)
    const fl = new THREE.Mesh(new THREE.ConeGeometry(0.04, 0.14, 6), M.lampGlow())
    fl.position.set(Math.cos(a) * 0.7, 3.68, Math.sin(a) * 0.7)
    fl.userData.isFlame = true
    g.add(c, fl)
  }
  return g
}

export function makeStairs() {
  const g = new THREE.Group()
  for (let i = 0; i < 6; i++) {
    const s = box(1.1, 0.16, 0.34, M.wood())
    s.position.set(0, 0.1 + i * 0.18, -i * 0.32)
    if (i === 4) s.rotation.z = 0.35 // broken tread
    g.add(s)
  }
  return g
}

export function makeLampSconce() {
  const g = new THREE.Group()
  const arm = box(0.06, 0.06, 0.3, M.iron())
  const cup = cyl(0.09, 0.05, 0.12, M.brass()); cup.position.set(0, 0.06, 0.16)
  const flame = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.16, 6), M.lampGlow())
  flame.position.set(0, 0.2, 0.16); flame.userData.isFlame = true
  g.add(arm, cup, flame)
  return g
}

/* ---------- pickups ---------- */
export function makePart() {
  const g = new THREE.Group()
  const core = new THREE.Mesh(new THREE.IcosahedronGeometry(0.16, 0), M.glowWarm())
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.045, 6, 12), M.brass())
  ring.userData.isGear = true; ring.userData.spin = 1.2
  const ring2 = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.045, 6, 12), M.iron())
  ring2.rotation.y = Math.PI / 2; ring2.userData.isGear = true; ring2.userData.spin = -0.9
  core.userData.isCore = true
  g.add(core, ring, ring2)
  const light = new THREE.PointLight(C.partGlow, 1.4, 4, 2)
  g.add(light)
  g.userData.core = core
  return g
}

export function makeInk() {
  const g = new THREE.Group()
  const bottle = cyl(0.09, 0.11, 0.2, M.iron()); bottle.position.y = 0.1
  const fluid = cyl(0.07, 0.09, 0.12, M.glowTeal()); fluid.position.y = 0.08
  const neck = cyl(0.03, 0.04, 0.08, M.brass()); neck.position.y = 0.24
  g.add(bottle, fluid, neck)
  return g
}

export function makeFragment() {
  const g = new THREE.Group()
  const page = new THREE.Mesh(
