/* glitch fringe: inverted triangles sprouting from doorframes */
export function makeGlitchFringe(w) {
  const g = new THREE.Group()
  const mat = new THREE.MeshBasicMaterial({ color: 0x8a5cff, wireframe: true, transparent: true, opacity: 0.8 })
  for (let i = 0; i < 5; i++) {
    const t = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.3, 3), mat)
    t.rotation.z = Math.PI
    t.position.set(-w / 2 + (i / 4) * w, 2.35 + Math.sin(i * 2.7) * 0.15, 0)
    g.add(t)
  }
  g.visible = false
  g.userData.isFringe = true
  return g
}
